#include <stdio.h>
int main() {
    int n, i, prime = 1;
    printf("Enter a number: ");
    scanf("%d", &n);

    if (n <= 1)
        prime = 0;
    else {
        for (i = 2; i <= n / 2; i++) {
            if (n % i == 0) {
                prime = 0;
                break;
            }
        }
    }

    if (prime)
        printf("Prime Number");
    else
        printf("Not a Prime Number");

    return 0;
}

#include <stdio.h>
int main() {
    int n, i;
    long long fact = 1;

    printf("Enter a number: ");
    scanf("%d", &n);

    for(i = 1; i <= n; i++) {
        fact *= i;
    }

    printf("Factorial = %lld", fact);

    return 0;
}

#include <stdio.h>
int main() {
    int n, i;
    int a = 0, b = 1, c;

    printf("Enter number of terms: ");
    scanf("%d", &n);

    for(i = 1; i <= n; i++) {
        printf("%d ", a);
        c = a + b;
        a = b;
        b = c;
    }

    return 0;
}

#include <stdio.h>
int main() {
    int n, temp, rev = 0, rem;

    printf("Enter a number: ");
    scanf("%d", &n);

    temp = n;

    while(temp != 0) {
        rem = temp % 10;
        rev = rev * 10 + rem;
        temp /= 10;
    }

    if(n == rev)
        printf("Palindrome Number");
    else
        printf("Not a Palindrome Number");

    return 0;
}

#include <stdio.h>
int main() {
    int n, rev = 0, rem;

    printf("Enter a number: ");
    scanf("%d", &n);

    while(n != 0) {
        rem = n % 10;
        rev = rev * 10 + rem;
        n /= 10;
    }

    printf("Reversed Number = %d", rev);

    return 0;
}
